const body = $input.first().json.body;
if (body?.type !== 'request.approved' || !body.data?.id || !body.data?.category) throw new Error('Evento de aprobación inválido');
const d = body.data;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
return [{ json: { subject: `CR Conecta: necesidad aprobada #${d.id}`, html: `<h2>Necesidad lista para recibir donaciones</h2><p><strong>Solicitud:</strong> ${esc(d.id)}</p><p><strong>Categoría:</strong> ${esc(d.category)}</p><p><strong>Zona:</strong> ${esc(d.zone)}</p><p><strong>Cantidad:</strong> ${esc(d.amount)} ${esc(d.unit)}</p><p><strong>Prioridad:</strong> ${esc(d.priority)}</p><p>Revisá la necesidad aprobada en CR Conecta antes de coordinar aportes.</p><small>Aviso de un prototipo académico; datos simulados.</small>` } }];

const body = $input.first().json.body;
if (body?.type !== 'donation.registered' || !body.data?.id || !body.data?.product) throw new Error('Evento de donación inválido');
const d = body.data;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
return [{ json: { subject: `CR Conecta: nueva donación #${d.id}`, html: `<h2>Nuevo aporte registrado</h2><p>El equipo tiene una nueva donación pendiente de seguimiento.</p><hr><h3>Comprobante de registro #${esc(d.id)}</h3><p><strong>Fecha:</strong> ${esc(d.date)}</p><p><strong>Producto:</strong> ${esc(d.product)}</p><p><strong>Categoría:</strong> ${esc(d.category)}</p><p><strong>Cantidad:</strong> ${esc(d.quantity)}</p><p><strong>Destino:</strong> ${esc(d.destination)}</p><p><strong>Estado:</strong> ${esc(d.status)}</p><p><strong>Tipo:</strong> ${d.anonymous ? 'Anónimo' : 'Registrado'}</p><hr><small>Comprobante de registro de un prototipo académico. No confirma recepción física, entrega ni beneficio fiscal.</small>` } }];
